function botonesCategorias() {
  return {
    inline_keyboard: [
      [{ text: "\ud83c\udfe2 Infraestructura", callback_data: "cat:Infraestructura" }],
      [{ text: "\ud83d\udd52 Horarios",         callback_data: "cat:Horarios" }],
      [{ text: "\ud83d\udcc4 Tr\u00e1mites Acad\u00e9micos", callback_data: "cat:Tramites" }],
      [{ text: "\ud83d\udcac Soporte y Cuentas", callback_data: "cat:Soporte" }],
      [{ text: "\ud83d\ude4b Hablar con un asesor", callback_data: "asesor" }]
    ]
  };
}

function botonesSubmenu(categoria) {
  const preguntas = MENU[categoria] || [];
  const filas = preguntas.map((p, i) => [{
    text: p.length > 60 ? p.substring(0, 57) + "..." : p,
    callback_data: "preg:" + categoria + ":" + i
  }]);
  filas.push([{ text: "\u2b05\ufe0f Volver al men\u00fa", callback_data: "volver_menu" }]);
  return { inline_keyboard: filas };
}

let salida = {};

if (item.callback_query) {
  const cq = item.callback_query;
  const chatId   = cq.message.chat.id;
  const messageId = cq.message.message_id;
  const data = cq.data;
  const callbackQueryId = cq.id;

  if (data === "volver_menu") {
    salida = { accion: "menu_categorias", chat_id: chatId, message_id: messageId,
               callback_query_id: callbackQueryId, session_id: "tg-" + chatId, canal: "telegram" };
  } else if (data === "asesor") {
    salida = { accion: "consulta", mensaje: "hablar con un asesor",
               chat_id: chatId, message_id: messageId,
               callback_query_id: callbackQueryId, session_id: "tg-" + chatId, canal: "telegram" };
  } else if (data.startsWith("cat:")) {
    const categoria = data.split(":")[1];
    salida = { accion: "submenu", categoria: categoria,
               chat_id: chatId, message_id: messageId,
               callback_query_id: callbackQueryId, session_id: "tg-" + chatId, canal: "telegram" };
  } else if (data.startsWith("preg:")) {
    const partes = data.split(":");
    const categoria = partes[1];
    const idx = parseInt(partes[2], 10);
    const preguntaReal = (MENU[categoria] || [])[idx] || "";
    salida = { accion: "consulta", mensaje: preguntaReal,
               chat_id: chatId, message_id: messageId,
               callback_query_id: callbackQueryId, session_id: "tg-" + chatId, canal: "telegram" };
  }
} else if (item.message) {
  const msg = item.message;
  const chatId = msg.chat.id;
  const texto = (msg.text || "").trim();
  if (texto === "/start" || texto.toLowerCase() === "menu" || texto.toLowerCase() === "/menu") {
    salida = { accion: "menu_categorias", chat_id: chatId, message_id: null,
               callback_query_id: null, session_id: "tg-" + chatId, canal: "telegram" };
  } else {
    salida = { accion: "consulta", mensaje: texto, chat_id: chatId, message_id: null,
               callback_query_id: null, session_id: "tg-" + chatId, canal: "telegram" };
  }
}

salida._botonesCategorias = botonesCategorias();
if (salida.accion === "submenu") {
  salida._botonesSubmenu = botonesSubmenu(salida.categoria);
}

return { json: salida };

// Recuperamos de forma segura los resultados de los nodos de MySQL
const filaSesion = $('Leer Sesion MySQL').all();
const filasFaqs = $('Leer FAQs MySQL').all();

// Recuperamos el item original (mensaje/session_id/canal/chat_id)
let original = {};
try {
  original = $('Preparar Item Web').item.json;
} catch (e) {
  try {
    original = $('Preparar Item Telegram').item.json;
  } catch (err) {
    original = { mensaje: "", session_id: "desconocida", canal: "web" };
  }
}

// Validamos de forma estricta si existe un registro de fallos previos
let fallosPrevios = 0;
if (filaSesion.length > 0 && filaSesion[0].json && filaSesion[0].json.fallos_consecutivos !== undefined) {
  fallosPrevios = Number(filaSesion[0].json.fallos_consecutivos);
}

// Mapeamos el arreglo de FAQs de la base de datos
const faqs = filasFaqs.map(f => f.json);

// Retornamos el objeto unificado garantizando que "mensaje" nunca sea undefined
return {
  json: {
    mensaje: original.mensaje || "",
    session_id: original.session_id || "web-" + Math.random().toString(36).substring(2, 10),
    canal: original.canal || "web",
    chat_id: original.chat_id || null,
    fallos_previos: fallosPrevios,
    faqs: faqs
  }
};

// ============================================================
// NODO: "Motor del Chatbot" (tipo Code, modo "Run Once for Each Item")
// Pegar este codigo completo en el nodo Code de n8n.
//
// ESPERA que el item de entrada tenga estas propiedades (json):
//   - mensaje        (string) texto escrito por el usuario
//   - session_id     (string) identificador de sesion
//   - canal          (string) 'web' o 'telegram'
//   - fallos_previos (number) contador de fallos traido de MySQL (0 si no existe)
//   - faqs           (array)  filas de la tabla knowledge_base traidas de MySQL
//
// DEVUELVE (json de salida):
//   tipo, texto, faq_id, categoria, puntaje, tokens (string),
//   resultado, nuevo_contador_fallos, session_id, canal, mensaje
// ============================================================

const STOP_WORDS = new Set([
  "el","la","los","las","un","una","unos","unas","de","del",
  "al","a","en","y","o","que","es","son","para","por","con",
  "sin","se","su","sus","mi","mis","tu","tus","yo","como",
  "donde","cual","cuales","cuando","quien","quienes","este",
  "esta","estos","estas","ese","esa","esos","esas","lo","le",
  "les","me","te","nos","ya","muy","mas","pero","si","no",
  "puedo","puedes","tengo","tiene","hay","soy","eres",
  "estoy","ser","fue","ha","he","han",
  "universidad","institucion","ofrecen","ofrece"
]);

function quitarTildes(texto) {
  return texto.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

function normalizarTexto(texto) {
  let t = String(texto).toLowerCase();
  t = quitarTildes(t);
  t = t.replace(/[^a-z0-9\s]/g, " ");
  t = t.replace(/\s+/g, " ").trim();
  return t;
}

function tokenizar(texto) {
  const normalizado = normalizarTexto(texto);
  if (!normalizado) return [];
  return normalizado.split(" ").filter(t => t && !STOP_WORDS.has(t));
}

function prefijoComun(a, b) {
  const n = Math.min(a.length, b.length);
  let i = 0;
  while (i < n && a[i] === b[i]) i++;
  return i;
}

function calcularPuntaje(tokensUsuario, palabrasClaveFaq) {
  let puntaje = 0;
  const setTokensUsuario = new Set(tokensUsuario);

  for (const fraseClave of palabrasClaveFaq) {
    const tokensClave = tokenizar(fraseClave);
    if (tokensClave.length === 0) continue;

    const coincidenciasExactas = tokensClave.filter(tk => setTokensUsuario.has(tk));
    puntaje += 3 * coincidenciasExactas.length;

    if (tokensClave.length > 1 && coincidenciasExactas.length === tokensClave.length) {
      puntaje += 3;
    }

    const tokensClaveRestantes = tokensClave.filter(tk => !setTokensUsuario.has(tk));
    for (const tu of setTokensUsuario) {
      for (const tk of tokensClaveRestantes) {
        if (prefijoComun(tu, tk) >= 5) {
          puntaje += 1;
        }
      }
    }
  }
  return puntaje;
}

function esComandoTransferencia(texto) {
  const comandos = new Set(["humano","asesor","soporte","agente","persona","operador"]);
  const tokens = new Set(tokenizar(texto));
  const frasesDirectas = ["hablar con un asesor","hablar con un humano","quiero un humano","necesito ayuda humana"];
  const textoNorm = normalizarTexto(texto);
  if (frasesDirectas.some(f => textoNorm.includes(normalizarTexto(f)))) return true;
  for (const c of comandos) if (tokens.has(c)) return true;
  return false;
}

const UMBRAL_MINIMO = 3;
const INTENTOS_MAX_FALLO = 3;

// ------------------------------------------------------------
// Punto de entrada del nodo Code
// ------------------------------------------------------------
const item = $input.item.json;
const mensaje = item.mensaje || "";
const sessionId = item.session_id || "desconocida";
const canal = item.canal || "web";
const fallosPrevios = Number(item.fallos_previos || 0);

// Mapeo seguro de FAQs con doble bloque de parseo y limpieza de cadenas
const faqs = (item.faqs || []).map(f => {
  let pc = f.palabras_clave;
  if (typeof pc === "string") {
    try {
      pc = JSON.parse(pc);
    } catch (e) {
      try {
        let limpia = pc.trim().replace(/^['"‘“‘]+|['"’ ”’]+$/g, '');
        pc = JSON.parse(limpia);
      } catch (err) {
        pc = [];
      }
    }
  }
  return {
    ...f,
    palabras_clave: Array.isArray(pc) ? pc : []
  };
});

let resultado;

if (esComandoTransferencia(mensaje)) {
  resultado = {
    tipo: "transferencia",
    texto: "Te comunico con un agente humano. Canales de atención presencial: Edificio Principal, Oficina de Registro. Horario: Lun-Vie 8:00 AM - 7:00 PM, Sab 8:00 AM - 12:00 PM. Correo: soporte@universidad.edu",
    faq_id: null,
    categoria: null,
    puntaje: 0,
    tokens: tokenizar(mensaje).join(" "),
    resultado_log: "transferencia_explicita",
    nuevo_contador_fallos: 0
  };
} else {
  const tokens = tokenizar(mensaje);
  let mejorFaq = null;
  let mejorPuntaje = 0;

  for (const faq of faqs) {
    const puntaje = calcularPuntaje(tokens, faq.palabras_clave || []);
    if (puntaje > mejorPuntaje) {
      mejorPuntaje = puntaje;
      mejorFaq = faq;
    }
  }

  if (mejorFaq && mejorPuntaje >= UMBRAL_MINIMO) {
    resultado = {
      tipo: "respuesta",
      texto: mejorFaq.respuesta,
      faq_id: mejorFaq.id,
      categoria: mejorFaq.categoria,
      puntaje: mejorPuntaje,
      tokens: tokens.join(" "),
      resultado_log: "respondida",
      nuevo_contador_fallos: 0
    };
  } else {
    const fallosActuales = fallosPrevios + 1;

    if (fallosActuales >= INTENTOS_MAX_FALLO) {
      resultado = {
        tipo: "transferencia",
        texto: "No logré identificar tu consulta tras varios intentos. Te transfiero con un agente humano. Correo: soporte@universidad.edu | Oficina de Registro, Lun-Vie 8:00 AM - 7:00 PM.",
        faq_id: null,
        categoria: null,
        puntaje: mejorPuntaje,
        tokens: tokens.join(" "),
        resultado_log: "transferencia_bucle_error",
        nuevo_contador_fallos: 0
      };
    } else {
      resultado = {
        tipo: "sin_resultado",
        texto: "No logré entender tu consulta. ¿Podrías reformularla? También puedes escribir 'menu' para ver las categorías disponibles, o 'asesor' para hablar con una persona.",
        faq_id: null,
        categoria: null,
        puntaje: mejorPuntaje,
        tokens: tokens.join(" "),
        resultado_log: "sin_resultado",
        nuevo_contador_fallos: fallosActuales
      };
    }
  }
}

return {
  json: {
    ...resultado,
    session_id: sessionId,
    canal,
    mensaje_original: mensaje
  }
};

