const motor = $('Motor del Chatbot').item.json;

const prepTelegram = $('Preparar Item Telegram').item.json;

const preguntaDetectada = motor.mensaje_original || "Consulta Realizada";

const textoFinal = `❓ *Pregunta:* ${preguntaDetectada}\n\n💡 *Respuesta:* ${motor.texto}`;

return {
  json: {
    chat_id: prepTelegram.chat_id,
    text: textoFinal,
    reply_markup: prepTelegram._botonesCategorias 
  }
};

const TELEGRAM_TOKEN = "8662701445:AAH4zydqY5ST0nEU750vp1Mqr3pdu2OEQRM";
const item = $input.item.json;

let texto = "";
let teclado = null;

if (item.accion === "menu_categorias") {
  texto = "\u00a1Hola! Soy tu Asistente Universitario Virtual \ud83c\udf93\n\u00bfEn que puedo ayudarte hoy?";
  teclado = item._botonesCategorias;
} else if (item.accion === "submenu") {
  texto = "Preguntas frecuentes \u2014 " + item.categoria + ":";
  teclado = item._botonesSubmenu;
}

const editar = !!item.message_id;
const metodo = editar ? "editMessageText" : "sendMessage";
const url = `https://api.telegram.org/bot${TELEGRAM_TOKEN}/${metodo}`;

const body = { chat_id: item.chat_id, text: texto, reply_markup: teclado };
if (editar) { body.message_id = item.message_id; }

return { json: { url, body, callback_query_id: item.callback_query_id || null } };

